"""Render saved evidence, never rerank using final test results."""
import html,json
from pathlib import Path
ROOT=Path(__file__).resolve().parent
def money(x):return f'${x:,.2f}'
def pct(x):return f'{x:.2f}%'
def config(c):
    return f"RSI {c['rsi']} / RSI EMA {c['rsi_ema']} · {c['entry_rule']} · BB {c['bb']} · {c['trend']} · "+(f"ATR(14) trail {c['atr_exit']}×" if c['atr_exit'] else 'opposite RSI exit')
def chart(points):
    sampled=points[::max(1,len(points)//500)]
    if points and sampled[-1]!=points[-1]:sampled.append(points[-1])
    low=min(p['equity'] for p in sampled);high=max(p['equity'] for p in sampled);span=max(1,high-low)
    coords=' '.join(f'{12+i*676/max(1,len(sampled)-1):.1f},{130-(p["equity"]-low)/span*110:.1f}' for i,p in enumerate(sampled))
    return f'<svg viewBox="0 0 700 150" role="img" aria-label="Held-out equity curve"><line x1="12" y1="130" x2="688" y2="130" stroke="#42536b"/><polyline points="{coords}" fill="none" stroke="#64cec3" stroke-width="2"/></svg><p class="muted">Equity range {money(low)} to {money(high)} · later 30% only</p>'
def main():
    r=json.loads((ROOT/'results.json').read_text());rows=[];cards=[]
    for d in r['datasets']:
        if not d['selected']:continue
        c=d['selected'][0];m=c['held_out']['metrics'];b=d['baseline']['held_out']['metrics'];stress=c['cost_stress'];folds=c['train_subperiods']
        passes=m['trades']>=10 and m['net_pnl']>0 and stress['net_pnl']>0 and all(f['net_pnl']>0 for f in folds)
        evidence='Further prospective validation required' if passes else 'Insufficient robust evidence'
        rows.append(f'<tr><td>{d["symbol"]} {d["resolution"]}</td><td>{money(c["train"]["net_pnl"])}</td><td class="{"positive" if m["net_pnl"]>0 else "negative"}">{money(m["net_pnl"])}</td><td>{pct(m["return_percent"])}</td><td>{pct(m["max_drawdown_percent"])}</td><td>{m["trades"]}</td><td>{money(stress["net_pnl"])}</td><td>{money(b["net_pnl"])}</td><td>{money(d["buy_hold_held_out_net_pnl"])}</td></tr>')
        cards.append(f'<article><h2>{d["symbol"]} · {d["resolution"]}</h2><p>{html.escape(config(c["config"]))}</p><p class="muted">{d["start_date"]} through {d["end_date"]} · {d["coverage"][d["resolution"]]["actual"]:,} audited candles · {d["settings"]["contracts"]} fixed contracts</p><p><b>{evidence}</b> · profit factor {m["profit_factor"] if m["profit_factor"] is None else round(m["profit_factor"],2)} · win rate {pct(m["win_rate"] or 0)}</p>{chart(c["held_out"]["equity"])}<p>Earlier training thirds: {", ".join(money(f["net_pnl"]) for f in folds)}. Stress drawdown: {pct(stress["max_drawdown_percent"])}.</p></article>')
    failures=''.join(f'<li>{html.escape(str(f))}</li>' for f in r['failures'])
    count=sum(d['combinations'] for d in r['datasets'])
    page=f'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Delta indicator research — completed evidence</title><style>body{{background:#101923;color:#e6edf4;font:16px/1.55 system-ui;margin:0}}main{{max-width:1280px;margin:44px auto;padding:0 24px}}h1{{font-size:36px;letter-spacing:-1px}}h2{{font-size:24px}}.muted{{color:#a4b2c3;font-size:14px}}.note,article{{background:#182533;border:1px solid #314254;padding:22px;border-radius:12px;margin:20px 0}}.scroll{{overflow-x:auto}}table{{border-collapse:collapse;width:100%;font-size:14px}}td,th{{padding:12px;text-align:right;border-bottom:1px solid #314254;white-space:nowrap}}td:first-child,th:first-child{{text-align:left}}.positive{{color:#79d2b1}}.negative{{color:#f5a4a4}}.grid{{display:grid;grid-template-columns:repeat(auto-fit,minmax(440px,1fr));gap:20px}}svg{{width:100%;height:auto}}a{{color:#80bdff}}@media(max-width:600px){{.grid{{display:block}}h1{{font-size:28px}}}}</style><main><p class="muted">SECTOR PULSE · PUBLIC DATA RESEARCH · 3 OCTOBER 2026</p><h1>Delta indicator combinations</h1><p>{count:,} tested configurations · BTC and ETH · seven timeframes · no execution changes.</p><div class="note"><b>Selection precedes the later test.</b> Each dataset has 486 combinations. Rank by training return minus twice training drawdown, requiring 20 training trades. Freeze three candidates, then evaluate the final 30%. This table shows the training-ranked first candidate, even when another has a better test result. No reranking or promotion uses the final test.</div><h2>What survived later data?</h2><div class="scroll"><table><thead><tr><th>Market</th><th>Train P&amp;L</th><th>Test P&amp;L</th><th>Test return</th><th>Test drawdown</th><th>Test trades</th><th>Stress P&amp;L</th><th>RSI baseline</th><th>Buy &amp; hold</th></tr></thead><tbody>{''.join(rows)}</tbody></table></div><p class="muted">USD quote-equivalent P&amp;L. Baseline uses RSI14/EMA14 and existing crossover/touch entries. Buy &amp; hold uses the same fixed contract quantity and approximate equivalent costs; it is directional long exposure, unlike the long/short strategies.</p><div class="note"><b>Comparable starting exposure, no leverage.</b> $10,000 capital; fixed contracts initially about 25% notional exposure per dataset. Small account drawdowns partly reflect this modest exposure. Per-fill fee allowance 5.9 bps (5 bps taker plus 18% GST), slippage 2 bps, half-spread 1 bp, adverse funding allowance 1 bp/day. Stress uses 5 bps slippage, 2 bps half-spread, 3 bps/day funding. No fee promotions assumed. <a href="https://www.delta.exchange/fees">Delta fee schedule</a>.</div><h2>Frozen configurations and equity</h2><div class="grid">{''.join(cards)}</div><h2>Coverage and limits</h2><p>One minute: 14 days. Five minutes: 75 days. Fifteen minutes, thirty minutes, one hour: 180 days. Six hours and daily: 365 days. Each ends 2 October 2026 IST. All requested candles must be complete and contiguous; 300 earlier bars warm indicators.</p><p>Grid: RSI lengths 10/14/21; RSI EMA lengths 9/14/21; crossover or existing crossover/touch; no Bollinger filter, expanding width, or squeeze release; no price trend filter, price EMA50, or Supertrend(14,3); no ATR stop, ATR(14) trailing 2×, or 3×. Bollinger(20,2), squeeze prior 100 widths/20th percentile/release three bars. Both long and short. All gates act on completed closes. Entry and opposite RSI exits fill next open. Trailing levels apply from the next candle; stop gaps fill at the worse open.</p><p>Finite search, not maximum attainable profit. Futures results do not represent ATM options. No historical option premiums, liquidation, margin, depth/partial fills, historical contract changes, or actual funding modeled. Drawdown uses close equity and may understate intrabar risk. Training thirds are stability diagnostics, not independent walk-forward selection. Multiple testing and the small final sample limit conviction. These inspected dates must not be reused as untouched validation.</p>{'<ul>'+failures+'</ul>' if failures else '<p>All fourteen datasets passed gap and warmup checks.</p>'}<p><a href="results.json">Download full parameters, training grid, frozen trades and evidence</a></p></main></html>'''
    (ROOT/'report.html').write_text(page)
    print(f'Rendered {len(rows)} datasets, {count} configurations')
if __name__=='__main__':main()
